function toMin(hhmm){
  var p=String(hhmm).split(':'); if(p.length<2) return null;
  var h=+p[0], m=+p[1]; if(isNaN(h)||isNaN(m)) return null;
  return h*60+m;
}
function sleepTime(bed, wake){
  var b=toMin(bed), w=toMin(wake);
  if(b==null||w==null) return {error:'时间格式须为 HH:MM'};
  var mins = (w - b + 1440) % 1440;
  var hours = Math.round(mins/6)/10;
  var quality, tip;
  if(mins < 360) { quality='睡眠不足'; tip='少于 6 小时，长期可能影响健康，建议提前作息。'; }
  else if(mins <= 540) { quality='睡眠充足'; tip='6–9 小时，符合多数成年人推荐区间。'; }
  else { quality='睡眠偏多'; tip='超过 9 小时，若伴不适可关注睡眠质量。'; }
  return {hours:hours, minutes:mins, quality:quality, tip:tip};
}
var EXPORTS={sleepTime:sleepTime};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SleepTimeForgePure = EXPORTS; }
